import FormControl, { type FormControlProps } from '@mui/material/FormControl';
import FormHelperText, {
  type FormHelperTextProps,
} from '@mui/material/FormHelperText';
import FormLabel, { type FormLabelProps } from '@mui/material/FormLabel';
import type { SxProps, Theme } from '@mui/material/styles';
import { mergeSx } from 'merge-sx';
import { forwardRef } from 'react';

const fieldRootSx: SxProps<Theme> = {
  gap: '4px',
  minWidth: 0,
  color: 'text.primary',
  fontFamily: 'fontFamily',
};
const fieldLabelSx: SxProps<Theme> = {
  fontSize: 12,
  lineHeight: '16px',
  fontWeight: 500,
  color: 'text.primary',
  '&.Mui-focused:not(.Mui-error):not(.Mui-disabled)': {
    color: 'secondary.main',
  },
  '&.Mui-disabled': { color: 'text.secondary' },
};
const fieldHelpSx: SxProps<Theme> = {
  margin: 0,
  fontSize: 13,
  lineHeight: '20px',
  '&.Mui-disabled': { color: 'text.secondary' },
};

export const FieldRoot = forwardRef<HTMLDivElement, FormControlProps>(
  function FieldRoot({ sx, ...props }, ref) {
    return <FormControl {...props} ref={ref} sx={mergeSx(fieldRootSx, sx)} />;
  }
);
export const FieldLabel = forwardRef<HTMLLabelElement, FormLabelProps>(
  function FieldLabel({ sx, ...props }, ref) {
    return <FormLabel {...props} ref={ref} sx={mergeSx(fieldLabelSx, sx)} />;
  }
);
export const FieldHelp = forwardRef<HTMLParagraphElement, FormHelperTextProps>(
  function FieldHelp({ sx, ...props }, ref) {
    return (
      <FormHelperText {...props} ref={ref} sx={mergeSx(fieldHelpSx, sx)} />
    );
  }
);
